def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    day = day_context['day']
    supply = float(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    opp_pressures = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                req = max(1.0, float(opp.get('water_requirement', WATER_REQ)))
                opp_pressures.append(float(bid) / req)

    if not alive_opponents:
        return float(min(budget, 18.0 if hp > 4 else 45.0))

    competitors = len(alive_opponents) + 1
    expected_share = supply / float(competitors)
    scarcity = expected_share < WATER_REQ
    severe_scarcity = supply <= 18.0
    abundant = supply >= 23.0

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_pressure = sum(opp_pressures) / float(len(opp_pressures)) if opp_pressures else 8.0

    danger = 0
    if hp <= 3:
        danger += 2
    elif hp <= 5:
        danger += 1
    if no_water_days >= 2:
        danger += 2
    elif no_water_days >= 1:
        danger += 1
    if scarcity:
        danger += 1
    if severe_scarcity:
        danger += 1

    reserve_days = max(1, 11 - int(day))
    soft_cap = budget / float(reserve_days)
    if danger >= 4:
        soft_cap = max(soft_cap, DAILY_SALARY * 1.15)
    elif danger >= 2:
        soft_cap = max(soft_cap, DAILY_SALARY * 0.85)
    else:
        soft_cap = max(soft_cap, DAILY_SALARY * 0.45)

    if danger >= 4:
        target = max(DAILY_SALARY * 1.0, highest_prev + 4.0, avg_pressure * WATER_REQ + 3.0)
    elif danger >= 2:
        target = max(DAILY_SALARY * 0.72, highest_prev * 0.82 + 3.0, avg_pressure * WATER_REQ * 0.88)
    else:
        if abundant:
            target = max(DAILY_SALARY * 0.22, highest_prev * 0.22)
        elif scarcity:
            target = max(DAILY_SALARY * 0.48, highest_prev * 0.55)
        else:
            target = max(DAILY_SALARY * 0.34, highest_prev * 0.35)

    rich_threats = 0
    for opp in alive_opponents:
        if opp.get('budget', 0) >= budget and opp.get('hp', 0) >= hp:
            rich_threats += 1
    if rich_threats >= 2 and danger <= 1:
        target *= 0.88

    if day >= 8:
        target *= 1.12
    if day >= 9 and danger >= 2:
        target *= 1.15

    bid = min(float(budget), min(target, soft_cap))

    if danger == 0 and highest_prev >= 140.0 and not severe_scarcity:
        bid = min(float(budget), DAILY_SALARY * 0.2)

    if hp <= 2 or no_water_days >= 2:
        bid = min(float(budget), max(bid, highest_prev + 6.0, DAILY_SALARY * 1.05))

    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return 10.0

    prev_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 100.0

    if my_status['hp'] <= 3:
        return min(my_status['budget'], 180.0)

    if supply < WATER_REQ:
        return min(my_status['budget'], avg_prev + 5.0)

    if supply >= WATER_REQ * 2:
        return min(my_status['budget'], 50.0)

    return min(my_status['budget'], avg_prev * 0.95)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    # collect yesterday's bids from alive opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # decide based on HP and budget
    hp = my_status['hp']
    budget = my_status['budget']
    low_hp = hp <= 3

    if yesterday_bids:
        max_prev = max(yesterday_bids)
        # if opponents were very aggressive, stay low if we're healthy
        if max_prev >= DAILY_SALARY * 0.85:
            if low_hp:
                return min(budget, DAILY_SALARY * 0.75)
            else:
                return min(budget, DAILY_SALARY * 0.25)
        else:
            # slightly above max_prev but not too high
            target = max_prev + 1.0
            target = min(target, DAILY_SALARY * 0.7)
            return min(budget, target)

    # no history (first day or opponents have no trace)
    if low_hp:
        return min(budget, DAILY_SALARY * 0.7)
    else:
        return min(budget, DAILY_SALARY * 0.3)
